//     except ValueError:
//         a = A(7)
//     # method: the hoisted local moves into the field
//     self.p = a  # tpyc: ok
inline void H::store(int32_t k) {
    std::optional<A> __slot_1;
    std::optional<A> __slot_2;
    A* a;
    {
        try {
            a = &*(__slot_1 = ::tpyapp::main::make(k));
        } catch (const ::tpy::ValueError&) {
            a = &*(__slot_2 = A(7));
        }
    }
    this->p = std::move((*a));
}

