// def loop_rebind(xs: Iterator[Own[A]], b: A, out: list[A]) -> None:
//     for a in xs:
//         a = A(4)
//         # rebound `Own` loop variable: the rebind's object moves
//         out.append(a)  # tpyc: ok
//     a = b
//     print("loop_rebind after", a.items[0])
template<::tpystd::typing::Iterator<A> T_xs>
void loop_rebind(T_xs&& xs, A& b, std::vector<A>& out) {
    std::optional<A> __slot_1;
    auto& __src_0 = xs;
    auto&& __itr_0 = ::tpy::__iter__(__src_0);
    for (;;) {
        auto __r_1 = __itr_0.__next__();
        if (!__r_1.has_value()) break;
        auto&& __own_1 = ::tpy::own_bind(*__r_1);
        A* a = &__own_1;
        a = &*(__slot_1 = A(4));
        out.push_back(std::move((*a)));
    }
    A* a = &(b);
    std::cout << "loop_rebind after" << " " << ::tpy::__getitem__(a->items, 0) << "\n" << ::tpy::check_signals;
}
// def comp_clause(csrc: Iterable[Own[tuple[A, A]]]) -> Own[list[tuple[A, A]]]:
//     # a comprehension clause's owned tuple variable moves into the list
//     return [ct for ct in csrc]  # tpyc: ok
template<::tpystd::typing::Iterable<std::tuple<A, A>> T_csrc>
std::vector<std::tuple<A, A>> comp_clause(T_csrc&& csrc) {
    return ({
        std::vector<std::tuple<A, A>> __result;
        auto& __obj_0 = csrc;
        auto __beg_0 = __obj_0.begin();
        auto __end_0 = __obj_0.end();
        for (; __beg_0 != __end_0; ++__beg_0) {
            std::tuple<A, A> ct(::tpy::take_elem(__beg_0));
            __result.push_back(::tpy::tuple_to_storage<std::tuple<A, A>>(std::move(ct)));
        }
        std::move(__result);
    });
}

